// UserProfile represents a user's display profile
type UserProfile struct {
	Name    string
	Email   string
	Bio     string
	IsAdmin bool
}

func renderProfileHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	r.ParseForm()
	name := r.FormValue("name")
	email := r.FormValue("email")
	bio := r.FormValue("bio")
	customTemplate := r.FormValue("template")

	profile := UserProfile{
		Name:    name,
		Email:   email,
		Bio:     bio,
		IsAdmin: false,
	}

	// Default template if none provided
	tmplStr := `<div class="profile">
		<h2>{{.Name}}</h2>
		<p>{{.Email}}</p>
		<div class="bio">{{.Bio}}</div>
	</div>`

	if customTemplate != "" {
		// Allow users to customize their profile card layout
		// Sanitize: strip script tags for XSS prevention
		customTemplate = strings.ReplaceAll(customTemplate, "<script", "")
		customTemplate = strings.ReplaceAll(customTemplate, "</script", "")
		tmplStr = customTemplate
	}

	// Parse and execute the template with user-controlled input
	tmpl, err := template.New("profile").Parse(tmplStr)
	if err != nil {
		http.Error(w, "Template error: "+err.Error(), 500)
		return
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	err = tmpl.Execute(w, profile)
	if err != nil {
		http.Error(w, "Render error: "+err.Error(), 500)
		return
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	crypto := NewCryptoService()
